/// Projects the coordinate's world position and, if it is in front of the
/// camera, queues a semi-transparent `POLY_FT4` centred on it. `arg1` selects
/// a 32-texel column of the texture page, `arg3` is the quad's rotation and
/// `arg2` its size, divided by depth so the quad shrinks with distance.
void waterDrawSpinU16(GfxCoord* arg0, u16 arg1, s16 arg2, s16 arg3)
{
    void**              scratch;
    EffectShapeScratch* head;
    EffectShapeScratch* block;
    POLY_FT4*           prim;
    SVECTOR*            vec;
    s32                 u0;
    s32                 u1;
    s32                 ang2;
    u16                 vz;

    scratch                   = SCRATCH_STACK_CURSOR_SLOT;
    head                      = *scratch;
    (head - 1)->worldPoint.vx = (u16)arg0->workm.t[0];
    block                     = head - 1;
    block->worldPoint.vy      = (u16)arg0->workm.t[1];
    vz                        = (u16)arg0->workm.t[2];
    block->worldPoint.vz      = vz;
    *scratch                  = block;
    vec                       = &block->worldPoint;
    gte_SetTransMatrix(&GsWSMATRIX);
    gte_SetRotMatrix(&GsWSMATRIX);
    gte_ldv0(vec);
    gte_rtps();
    gte_stsxy(&(head - 1)->screenX);
    gte_stflg(&(head - 1)->projectionFlags);
    if (block->projectionFlags >= 0) {
        gte_stszotz(&(head - 1)->depth);
        block->depth++;
        prim           = gGpuPrimCursor;
        gGpuPrimCursor = prim + 1;
        setPolyFT4(prim);
        setSemiTrans(prim, 1);
        setShadeTex(prim, 1);
        prim->tpage = 0x2B;
        prim->clut  = 0x43D3;
        u0          = arg1 << 5;
        u1          = u0 + 0x1F;
        setUV4(prim, u0, 0xE0, u1, 0xE0, u0, 0xFF, u1, 0xFF);
        block->extent.corner.x = (((arg2 * 31) / block->depth) * rsin(arg3)) >> 12;
        block->extent.corner.y = (((arg2 * 31) / block->depth) * rcos(arg3)) >> 12;
        prim->x0               = block->screenX + (u16)block->extent.corner.x;
        prim->x3               = block->screenX - (u16)block->extent.corner.x;
        prim->y0               = block->screenY - (u16)block->extent.corner.y;
        prim->y3               = block->screenY + (u16)block->extent.corner.y;
        ang2                   = arg3 + 0x400;
        block->extent.corner.x = (((arg2 * 31) / block->depth) * rsin(ang2)) >> 12;
        block->extent.corner.y = (((arg2 * 31) / block->depth) * rcos(ang2)) >> 12;
        prim->x1               = block->screenX + (u16)block->extent.corner.x;
        prim->x2               = block->screenX - (u16)block->extent.corner.x;
        prim->y1               = block->screenY - (u16)block->extent.corner.y;
        prim->y2               = block->screenY + (u16)block->extent.corner.y;
        addPrim(GPU_ORDERING_TABLE_ENTRY_AT_BYTE_OFFSET(((((u32)block->depth << gDisplayState.otDepthShift) >> 2) & GPU_ORDERING_TABLE_DEPTH_BYTE_MASK)),
                prim);
    }
    SCRATCH_POP_AT(scratch, EffectShapeScratch);
}

void waterDrawTileU16(GfxCoord* arg0, s32 arg1, s32 arg2)
{
    EffectCentreScratch* block;
    POLY_FT4*            prim;
    u16                  idx;
    u32                  cell;
    s32                  row;
    u8                   u0;
    u8                   u1;
    u8                   v0;
    u8                   v1;

    idx                  = arg1;
    block                = SCRATCH_STACK_RESERVE_BLOCK(EffectCentreScratch);
    block->worldPoint.vx = arg0->workm.t[0];
    block->worldPoint.vy = arg0->workm.t[1];
    block->worldPoint.vz = arg0->workm.t[2];
    gte_SetTransMatrix(&GsWSMATRIX);
    gte_SetRotMatrix(&GsWSMATRIX);
    gte_ldv0(&block->worldPoint);
    gte_rtps();
    gte_stsxy(&block->screenX);
    gte_stflg(&block->projectionFlags);
    if (block->projectionFlags >= 0) {
        gte_stszotz(&block->depth);
        block->depth++;
        prim           = gGpuPrimCursor;
        gGpuPrimCursor = prim + 1;
        setlen(prim, 9);
        setcode(prim, 0x2F);
        prim->tpage = 0x2C;
        prim->clut  = 0x4393;
        cell        = idx;
        u0          = (cell & 3) * 0x38;
        row         = ((cell & 7) >> 2) * 0x38;
        v0          = row;
        v1          = row + 0x37;
        u1          = u0 + 0x37;
        setUV4(prim, u0, v0, u1, v0, u0, v1, u1, v1);
        block->screenExtent = ((s16)arg2 * 55) / block->depth;
        prim->x0 = prim->x2 = block->screenX - block->screenExtent;
        prim->x1 = prim->x3 = block->screenX + block->screenExtent;
        prim->y0 = prim->y1 = block->screenY - block->screenExtent - (block->screenExtent >> 1);
        prim->y2 = prim->y3 = block->screenY + (block->screenExtent >> 1);
        addPrim(GPU_ORDERING_TABLE_ENTRY_AT_BYTE_OFFSET(((((u32)block->depth << gDisplayState.otDepthShift) >> 2) & GPU_ORDERING_TABLE_DEPTH_BYTE_MASK)),
                prim);
    }
    SCRATCH_STACK_RELEASE_BLOCK(EffectCentreScratch);
}

/// Writes the signed pixel offset to one rotated drift-sprite corner.
///
/// `projection` borrows a live workspace with positive `depth`; only
/// `extent.corner` changes and no pointer is retained. The signed half-diagonal
/// is `sizeFactor * 47 / depth` pixels, truncated toward zero before rotation.
/// Products must fit s32; the Q12 arithmetic shift rounds negative products down.
///
/// `cornerAngle` is absolute, in 4096 units per turn. X points right and Y up:
/// with a positive half-diagonal, zero points up and a quarter turn points right.
/// The drawer subtracts Y from the centre and uses opposite signs for each pair
/// of corners, repeating a quarter turn later for the other pair.
static __inline__ void _shelterR48RotateDriftCorner(EffectShapeScratch* projection, s16 sizeFactor, s32 cornerAngle)
{
    enum {
        SHELTER_R48_DRIFT_PERSPECTIVE_SCALE  = 47, // Multiplier in the depth-divided half-diagonal numerator
        SHELTER_R48_DRIFT_TRIG_FRACTION_BITS = 12  // Fractional bits in rsin/rcos samples; 4096 represents 1.0
    };
    s32 halfDiagonalPixels;
    s32 trigSample;

    trigSample                  = rsin(cornerAngle);
    halfDiagonalPixels          = (sizeFactor * SHELTER_R48_DRIFT_PERSPECTIVE_SCALE) / projection->depth;
    projection->extent.corner.x = (halfDiagonalPixels * trigSample) >> SHELTER_R48_DRIFT_TRIG_FRACTION_BITS;
    trigSample                  = rcos(cornerAngle);
    halfDiagonalPixels          = (sizeFactor * SHELTER_R48_DRIFT_PERSPECTIVE_SCALE) / projection->depth;
    projection->extent.corner.y = (halfDiagonalPixels * trigSample) >> SHELTER_R48_DRIFT_TRIG_FRACTION_BITS;
}

/// Binds Shelter R48's exported `void (Task*)` callback for this drift instance.
///
/// Function-identifier alias supplied before the fragment and cleared after it.
/// Used only as the definition name; no arguments, captures or constructed tokens.
#define EFFECT_SPRITE_DRIFT_TASK shelterR48SpriteDriftTask
/// Binds the twelve-frame drift drawer: `(const GfxCoord*, u16 frameAndPalette, s16 size, s16 angle)`.
///
/// Function-identifier alias supplied before the fragment and cleared after it.
/// Arguments are evaluated once; the coordinate is borrowed, size is a perspective
/// numerator, and angle uses 4096 units per turn. No captures or constructed tokens.
#define EFFECT_SPRITE_DRIFT_DRAW_BANKED _shelterR48DrawBankedDriftSprite
/// Binds the ten-frame drift drawer with the same coordinate, packed-frame, size and angle contract.
///
/// Function-identifier alias supplied before the fragment and cleared after it.
/// Arguments are evaluated once; the coordinate is borrowed, size is a perspective
/// numerator, and angle uses 4096 units per turn. No captures or constructed tokens.
#define EFFECT_SPRITE_DRIFT_DRAW_ALTERNATE _shelterR48DrawAlternateDriftSprite
/// Selects the drift sprite's palette bank from the spawn argument's sign bit.
///
/// Define as integer 1 before including `effect_sprite_drift.inc.c`, as Shelter
/// R48 does; 0 or undefined selects the default encoding (bit 31 chooses the
/// drawer, bits 28..30 choose the palette bank). With 1, initialization chooses
/// the banked drawer when bits 28..31 are all zero, otherwise the alternate drawer. Bit 31 alone
/// sets `EffectWork::pos.vx` to 0 or 0x1000, ORed with the animation cell index
/// in the drawer's u16 argument. Both R48 drawers use bank 1 for CLUT 0x428F
/// and bank 0 for their ordinary palettes.
///
/// Suspended updates choose A for a nonnegative spawn argument and B for a
/// negative one, regardless of the running drawer state, retaining the current
/// cell and bank. The bank is initialized only on the first running update.
/// `EFFECT_SPRITE_DRIFT_PAUSED_DRAW_A_UNBANKED` overrides suspended selection.
/// The fragment tests this configuration with #if/#elif and undefines it
/// after inclusion.
#define EFFECT_SPRITE_DRIFT_SIGN_BANK 1
/// Applies fixed negative-Y acceleration to every moving drift sprite.
///
/// Define as integer 1 before including `effect_sprite_drift.inc.c`, as Shelter
/// R48 does; 0 or undefined retains movement kind 7's age-dependent positive-Y
/// acceleration. Kind is bits 24..27 of `Task::spawnArg1.value`. With 1, both
/// drawer states ignore kind: state 1 subtracts 2 from Y velocity per moving
/// update, and state 2 subtracts 1 (coordinate units per update squared).
/// Position advances with the current velocity before this signed-halfword
/// velocity update. Initialization, suspension and sprites with `EffectWork::step`
/// zero do not accelerate. The fragment tests this switch with #if and undefines
/// it after inclusion.
#define EFFECT_SPRITE_DRIFT_FIXED_NEGATIVE_Y_ACCELERATION 1
#include "../../shared/effect_sprite_drift.inc.c"

/// Draws a rotating twelve-cell sprite with a per-cell or alternate palette.
///
/// `coord->workm` must be composed for `GsWSMATRIX`; translation is narrowed
/// to s16. Bits 0..11 of `frameAndPalette` hold cell 0..11; any selector in
/// bits 12..15 uses CLUT 0x428F instead of the cell palette on VRAM row 270.
/// The five-column sheet has 48-texel cells at V=112 on texture page 0x2C.
///
/// `size * 47 / (SZ3/4 + 1)` is the signed pixel half-diagonal before Q12
/// rotation; `angle` uses 4096 units per turn. A nonnegative GTE FLAG queues
/// an additive raw-texture FT4, also sorted with the biased depth. One scratch
/// block is borrowed and released on every path; the initialized scratch stack
/// and primitive cursor must provide capacity. No pointer is retained.
static void _shelterR48DrawBankedDriftSprite(const GfxCoord* coord, u16 frameAndPalette, s16 size, s16 angle)
{
    enum {
        // Signed row offsets wrap to GPU UV bytes; last - first is 47 modulo 256.
        SHELTER_R48_DRIFT_FIRST_TEXEL_ROW   = 112,
        SHELTER_R48_DRIFT_LAST_TEXEL_ROW    = -97,
        SHELTER_R48_DRIFT_FRAME_MASK        = 0xFFF,
        SHELTER_R48_DRIFT_PALETTE_SHIFT     = 12,
        SHELTER_R48_DRIFT_CELLS_PER_ROW     = 5,
        SHELTER_R48_DRIFT_CELL_PITCH_TEXELS = 48,
        SHELTER_R48_DRIFT_UV_SPAN_TEXELS    = 47,
        SHELTER_R48_DRIFT_QUARTER_TURN      = 0x400,
        SHELTER_R48_DRIFT_PACKET_WORDS      = sizeof(POLY_FT4) / sizeof(u32) - 1,
        SHELTER_R48_DRIFT_PACKET_CODE       = 0x2F,
        SHELTER_R48_DRIFT_TEXTURE_PAGE      = 0x2C,
        SHELTER_R48_DRIFT_ALTERNATE_CLUT    = 0x428F,
        SHELTER_R48_DRIFT_FIRST_FRAME_CLUT  = 0x4380,
        SHELTER_R48_DRIFT_CLUT_COLUMN_MASK  = 0x3F
    };
    EffectShapeScratch* scratchEnd;
    EffectShapeScratch* projection;
    POLY_FT4*           quad;
    u16                 cellColumn;
    u16                 cellRow;
    s32                 cellU;
    s32                 cellV;
    s32                 cornerAngle;
    s32                 perpendicularAngle;
    s32                 paletteSelector;
    s32                 frameIndex;

    scratchEnd                      = SCRATCH_STACK_CURSOR(EffectShapeScratch);
    (scratchEnd - 1)->worldPoint.vx = coord->workm.t[0];
    SCRATCH_STACK_CURSOR(void)      = scratchEnd - 1;
    projection                      = SCRATCH_STACK_CURSOR(EffectShapeScratch);
    projection->worldPoint.vy       = coord->workm.t[1];
    projection->worldPoint.vz       = coord->workm.t[2];
    frameIndex                      = frameAndPalette & SHELTER_R48_DRIFT_FRAME_MASK;
    paletteSelector                 = frameAndPalette >> SHELTER_R48_DRIFT_PALETTE_SHIFT;
    // Project the composed centre; the quad rotates only in screen space.
    gte_SetTransMatrix(&GsWSMATRIX);
    gte_SetRotMatrix(&GsWSMATRIX);
    gte_ldv0(&projection->worldPoint);
    gte_rtps();
    gte_stsxy(&(scratchEnd - 1)->screenX);
    gte_stflg(&(scratchEnd - 1)->projectionFlags);
    if (projection->projectionFlags >= 0) {
        gte_stszotz(&(scratchEnd - 1)->depth);
        projection->depth++;
        quad           = gGpuPrimCursor;
        gGpuPrimCursor = quad + 1;
        setlen(quad, SHELTER_R48_DRIFT_PACKET_WORDS);
        setcode(quad, SHELTER_R48_DRIFT_PACKET_CODE);
        quad->tpage = SHELTER_R48_DRIFT_TEXTURE_PAGE;
        if (paletteSelector != 0) {
            quad->clut = SHELTER_R48_DRIFT_ALTERNATE_CLUT;
        } else {
            quad->clut = (frameIndex & SHELTER_R48_DRIFT_CLUT_COLUMN_MASK) | SHELTER_R48_DRIFT_FIRST_FRAME_CLUT;
        }
        cellColumn  = (u16)frameIndex % SHELTER_R48_DRIFT_CELLS_PER_ROW;
        cellRow     = (u16)frameIndex / SHELTER_R48_DRIFT_CELLS_PER_ROW;
        cornerAngle = angle;
        cellU       = cellColumn * SHELTER_R48_DRIFT_CELL_PITCH_TEXELS;
        cellV       = cellRow * SHELTER_R48_DRIFT_CELL_PITCH_TEXELS;
        setUV4(quad, cellU, cellV + SHELTER_R48_DRIFT_FIRST_TEXEL_ROW, cellU + SHELTER_R48_DRIFT_UV_SPAN_TEXELS, cellV + SHELTER_R48_DRIFT_FIRST_TEXEL_ROW, cellU, cellV + SHELTER_R48_DRIFT_LAST_TEXEL_ROW, cellU + SHELTER_R48_DRIFT_UV_SPAN_TEXELS, cellV + SHELTER_R48_DRIFT_LAST_TEXEL_ROW);
        _shelterR48RotateDriftCorner(projection, size, cornerAngle);
        quad->x0           = projection->screenX + (u16)projection->extent.corner.x;
        quad->x3           = projection->screenX - (u16)projection->extent.corner.x;
        quad->y0           = projection->screenY - (u16)projection->extent.corner.y;
        quad->y3           = projection->screenY + (u16)projection->extent.corner.y;
        perpendicularAngle = cornerAngle + SHELTER_R48_DRIFT_QUARTER_TURN;
        _shelterR48RotateDriftCorner(projection, size, perpendicularAngle);
        quad->x1 = projection->screenX + (u16)projection->extent.corner.x;
        quad->x2 = projection->screenX - (u16)projection->extent.corner.x;
        quad->y1 = projection->screenY - (u16)projection->extent.corner.y;
        quad->y2 = projection->screenY + (u16)projection->extent.corner.y;
        // Sort by projection depth; the GPU consumes a complete textured-quad packet.
        addPrim(GPU_ORDERING_TABLE_ENTRY_AT_BYTE_OFFSET(((((u32)projection->depth << gDisplayState.otDepthShift) >> 2) & GPU_ORDERING_TABLE_DEPTH_BYTE_MASK)),
                quad);
    }
    SCRATCH_STACK_RELEASE_BLOCK(EffectShapeScratch);
}

/// Draws a rotating ten-cell sprite with a base or alternate palette.
///
/// `coord->workm` must be composed for `GsWSMATRIX`; translation is narrowed
/// to s16. Bits 0..11 of `frameAndPalette` hold cell 0..9; any nonzero selector
/// in bits 12..15 uses CLUT 0x428F instead of 0x43D0. The five-column sheet
/// has 48-texel cells at V=128 on texture page 0x2B.
///
/// `size * 47 / (SZ3/4 + 1)` is the signed pixel half-diagonal before Q12
/// rotation; `angle` uses 4096 units per turn. A nonnegative GTE FLAG queues
/// an additive raw-texture FT4, sorted with biased depth. One scratch block
/// is borrowed and released on every path; the initialized scratch stack and
/// primitive cursor must provide capacity. No pointer is retained.
static void _shelterR48DrawAlternateDriftSprite(const GfxCoord* coord, u16 frameAndPalette, s16 size, s16 angle)
{
    enum {
        // Signed row offsets wrap to GPU UV bytes; last - first is 47 modulo 256.
        SHELTER_R48_DRIFT_FIRST_TEXEL_ROW   = -128,
        SHELTER_R48_DRIFT_LAST_TEXEL_ROW    = -81,
        SHELTER_R48_DRIFT_FRAME_MASK        = 0xFFF,
        SHELTER_R48_DRIFT_PALETTE_SHIFT     = 12,
        SHELTER_R48_DRIFT_CELLS_PER_ROW     = 5,
        SHELTER_R48_DRIFT_CELL_PITCH_TEXELS = 48,
        SHELTER_R48_DRIFT_UV_SPAN_TEXELS    = 47,
        SHELTER_R48_DRIFT_QUARTER_TURN      = 0x400,
        SHELTER_R48_DRIFT_PACKET_WORDS      = sizeof(POLY_FT4) / sizeof(u32) - 1,
        SHELTER_R48_DRIFT_PACKET_CODE       = 0x2F,
        SHELTER_R48_DRIFT_TEXTURE_PAGE      = 0x2B,
        SHELTER_R48_DRIFT_ALTERNATE_CLUT    = 0x428F,
        SHELTER_R48_DRIFT_BASE_CLUT         = 0x43D0
    };
    EffectShapeScratch* scratchEnd;
    EffectShapeScratch* projection;
    POLY_FT4*           quad;
    u16                 cellColumn;
    u16                 cellRow;
    s32                 cellU;
    s32                 cellV;
    s32                 cornerAngle;
    s32                 perpendicularAngle;
    s32                 paletteSelector;
    u16                 frameIndex;

    scratchEnd                      = SCRATCH_STACK_CURSOR(EffectShapeScratch);
    (scratchEnd - 1)->worldPoint.vx = coord->workm.t[0];
    SCRATCH_STACK_CURSOR(void)      = scratchEnd - 1;
    projection                      = SCRATCH_STACK_CURSOR(EffectShapeScratch);
    projection->worldPoint.vy       = coord->workm.t[1];
    projection->worldPoint.vz       = coord->workm.t[2];
    frameIndex                      = frameAndPalette & SHELTER_R48_DRIFT_FRAME_MASK;
    paletteSelector                 = frameAndPalette >> SHELTER_R48_DRIFT_PALETTE_SHIFT;
    // Project the composed centre; the quad rotates only in screen space.
    gte_SetTransMatrix(&GsWSMATRIX);
    gte_SetRotMatrix(&GsWSMATRIX);
    gte_ldv0(&projection->worldPoint);
    gte_rtps();
    gte_stsxy(&(scratchEnd - 1)->screenX);
    gte_stflg(&(scratchEnd - 1)->projectionFlags);
    if (projection->projectionFlags >= 0) {
        gte_stszotz(&(scratchEnd - 1)->depth);
        projection->depth++;
        quad           = gGpuPrimCursor;
        gGpuPrimCursor = quad + 1;
        setlen(quad, SHELTER_R48_DRIFT_PACKET_WORDS);
        setcode(quad, SHELTER_R48_DRIFT_PACKET_CODE);
        quad->tpage = SHELTER_R48_DRIFT_TEXTURE_PAGE;
        if (paletteSelector != 0) {
            quad->clut = SHELTER_R48_DRIFT_ALTERNATE_CLUT;
        } else {
            quad->clut = SHELTER_R48_DRIFT_BASE_CLUT;
        }
        cellColumn  = (u16)frameIndex % SHELTER_R48_DRIFT_CELLS_PER_ROW;
        cellRow     = (u16)frameIndex / SHELTER_R48_DRIFT_CELLS_PER_ROW;
        cornerAngle = angle;
        cellU       = cellColumn * SHELTER_R48_DRIFT_CELL_PITCH_TEXELS;
        cellV       = cellRow * SHELTER_R48_DRIFT_CELL_PITCH_TEXELS;
        setUV4(quad, cellU, cellV + SHELTER_R48_DRIFT_FIRST_TEXEL_ROW, cellU + SHELTER_R48_DRIFT_UV_SPAN_TEXELS, cellV + SHELTER_R48_DRIFT_FIRST_TEXEL_ROW, cellU, cellV + SHELTER_R48_DRIFT_LAST_TEXEL_ROW, cellU + SHELTER_R48_DRIFT_UV_SPAN_TEXELS, cellV + SHELTER_R48_DRIFT_LAST_TEXEL_ROW);
        _shelterR48RotateDriftCorner(projection, size, cornerAngle);
        quad->x0           = projection->screenX + (u16)projection->extent.corner.x;
        quad->x3           = projection->screenX - (u16)projection->extent.corner.x;
        quad->y0           = projection->screenY - (u16)projection->extent.corner.y;
        quad->y3           = projection->screenY + (u16)projection->extent.corner.y;
        perpendicularAngle = cornerAngle + SHELTER_R48_DRIFT_QUARTER_TURN;
        _shelterR48RotateDriftCorner(projection, size, perpendicularAngle);
        quad->x1 = projection->screenX + (u16)projection->extent.corner.x;
        quad->x2 = projection->screenX - (u16)projection->extent.corner.x;
        quad->y1 = projection->screenY - (u16)projection->extent.corner.y;
        quad->y2 = projection->screenY + (u16)projection->extent.corner.y;
        // Sort by projection depth; the GPU consumes a complete textured-quad packet.
        addPrim(GPU_ORDERING_TABLE_ENTRY_AT_BYTE_OFFSET(((((u32)projection->depth << gDisplayState.otDepthShift) >> 2) & GPU_ORDERING_TABLE_DEPTH_BYTE_MASK)),
                quad);
    }
    SCRATCH_STACK_RELEASE_BLOCK(EffectShapeScratch);
}

void func_shelter_r48_801810B0(Task* task)
{
    EffectWork* work;
    GfxCoord*   coord;
    EffectWork* eff;
    u8          rgb[3];
    s32         step;
    s16         scale;

    work  = task->spawnArg2.pointer;
    coord = task->extra.coordBody->coord;
    if (gRoomEffectState->effectControl < ROOM_EFFECT_CONTROL_CANCEL_MIN) {
        work->age++;
        switch (task->state) {
            case 0:
                coord->parent = work->parent;
                gfxRotMatrixX(&coord->coord, -0x400, GRAPHICS_ROTATION_REPLACE);
                coord->coord.t[2]   = 0;
                coord->coord.t[1]   = 0;
                coord->coord.t[0]   = 0;
                coord->composeStamp = GRAPHICS_COORD_DIRTY;
                actorRenderComposeCoord(coord);
                task->state = 1;
                work->scale = 0;
                work->angle = 0x100;
                work->step  = 0x100 / task->spawnArg1.value;
            case 1:
                if (gRoomEffectState->effectControl != ROOM_EFFECT_CONTROL_RUNNING) {
                    rgb[0] = work->scale;
                    rgb[1] = work->scale >> 1;
                    rgb[2] = work->scale >> 2;
                    Gp_DrawRing(coord, work->angle, rgb);
                    Gp_DrawRing(coord, (s16)((u16)work->angle * 2), rgb);
                    Gp_DrawArc(coord, (s16)((task->spawnArg1.value % 10) * (work->scale << 2)), 0x100, rgb);
                    return;
                }
                scale        = work->scale;
                step         = (u16)work->step;
                work->scale  = scale + step;
                work->angle += (u16)work->step * 8;
                task->spawnArg1.value--;
                rgb[0] = work->scale;
                rgb[1] = work->scale >> 1;
                rgb[2] = work->scale >> 2;
                Gp_DrawRing(coord, work->angle, rgb);
                Gp_DrawRing(coord, (s16)((u16)work->angle * 2), rgb);
                Gp_DrawArc(coord, (s16)((task->spawnArg1.value % 10) * (work->scale << 2)), 0x100, rgb);
                if (task->spawnArg1.value == 0) {
                    work->scale = 0xFF;
                    task->state = 2;
                    eff         = Gp_SpawnEff(EFFECT_SHELTER_R48_SHOCKWAVE_RINGS, coord, 0, NULL);
                    if (eff != NULL) {
                        taskReparent(task, eff->task);
                    }
                }
                return;
            case 2:
                if (work->scale >= 5) {
                    rgb[0] = work->scale;
                    rgb[1] = work->scale >> 1;
                    rgb[2] = work->scale >> 2;
                    Gp_DrawRing(coord, work->angle, rgb);
                    Gp_DrawRing(coord, (s16)((u16)work->angle * 2), rgb);
                    if (gRoomEffectState->effectControl == ROOM_EFFECT_CONTROL_RUNNING) {
                        work->scale -= 4;
                    }
                    Gp_DrawFadeQuad(rgb, 1);
                    return;
                }
                break;
            default:
                return;
        }
    }
    effectKillTask(work, task);
}

void func_shelter_r48_8018147C(Task* task)
{
    EffectWork* work;
    GfxCoord*   coord;
    MATRIX*     m;
    u8          rgb[3];

    work  = task->spawnArg2.pointer;
    coord = task->extra.coordBody->coord;
    if (gRoomEffectState->effectControl != ROOM_EFFECT_CONTROL_RUNNING) {
        func_shelter_r48_8017F124(work, coord, 3);
        func_shelter_r48_8017F124(work, coord, 4);
        func_shelter_r48_8017F124(work, coord, 5);
        if (gRoomEffectState->effectControl < ROOM_EFFECT_CONTROL_CANCEL_MIN) {
            return;
        }
    } else {
        work->age++;
        switch (task->state) {
            case 0:
                m                                = &coord->coord;
                coord->parent                    = work->parent;
                MATRIX_PAIR(&coord->coord, 0, 0) = 0x1000;
                MATRIX_PAIR(m, 0, 2)             = 0;
                MATRIX_PAIR(m, 1, 1)             = 0x1000;
                MATRIX_PAIR(m, 2, 0)             = 0;
                m->m[2][2]                       = 0x1000;
                coord->coord.t[2]                = 0;
                coord->coord.t[1]                = 0;
                coord->coord.t[0]                = 0;
                coord->composeStamp              = GRAPHICS_COORD_DIRTY;
                actorRenderComposeCoord(coord);
                work->age   = 1;
                work->scale = 0x80;
                task->state = 1;
                return;
            case 1:
                func_shelter_r48_8017F124(work, coord, 3);
                func_shelter_r48_8017F124(work, coord, 4);
                func_shelter_r48_8017F124(work, coord, 5);
                work->angle  += 0x10;
                work->period += 0x10;
                work->step   += 0x10;
                rgb[0]        = work->scale;
                rgb[1]        = work->scale >> 1;
                rgb[2]        = work->scale >> 2;
                Gp_DrawFadeQuad(rgb, 1);
                if (work->age >= 0x31) {
                    task->state = 2;
                }
                return;
            case 2:
                if (work->scale >= 0x11) {
                    work->scale  -= 0x10;
                    work->angle  += 0x10;
                    work->period += 0x10;
                    work->step   += 0x10;
                    func_shelter_r48_8017F124(work, coord, 3);
                    func_shelter_r48_8017F124(work, coord, 4);
                    func_shelter_r48_8017F124(work, coord, 5);
                    rgb[0] = work->scale;
                    rgb[1] = work->scale >> 1;
                    rgb[2] = work->scale >> 2;
                    Gp_DrawFadeQuad(rgb, 1);
                    return;
                }
                break;
            default:
                return;
        }
    }
    effectKillTask(work, task);
}

void func_shelter_r48_80181704(Task* task)
{
    EffectWork* work;
    GfxCoord*   coord;
    MATRIX*     m;
    u8          rgb[3];
    s32         step;
    s16         scale;

    work  = task->spawnArg2.pointer;
    coord = task->extra.coordBody->coord;
    if (gRoomEffectState->effectControl < ROOM_EFFECT_CONTROL_CANCEL_MIN) {
        work->age++;
        switch (task->state) {
            case 0:
                m                                = &coord->coord;
                coord->parent                    = work->parent;
                MATRIX_PAIR(&coord->coord, 0, 0) = 0x1000;
                MATRIX_PAIR(m, 0, 2)             = 0;
                MATRIX_PAIR(m, 1, 1)             = 0x1000;
                MATRIX_PAIR(m, 2, 0)             = 0;
                m->m[2][2]                       = 0x1000;
                coord->coord.t[2]                = 0;
                coord->coord.t[1]                = 0;
                coord->coord.t[0]                = 0;
                coord->composeStamp              = GRAPHICS_COORD_DIRTY;
                actorRenderComposeCoord(coord);
                task->state           = 1;
                task->spawnArg1.value = 0x1E;
                work->scale           = 0;
                work->angle           = 0x100;
                work->step            = 0x100 / task->spawnArg1.value;
            case 1:
                if (gRoomEffectState->effectControl != ROOM_EFFECT_CONTROL_RUNNING) {
                    rgb[0] = work->scale;
                    rgb[1] = work->scale >> 2;
                    rgb[2] = work->scale >> 1;
                    Gp_DrawRing(coord, work->angle, rgb);
                    Gp_DrawRing(coord, (s16)((u16)work->angle * 2), rgb);
                    Gp_DrawArc(coord, (s16)((u16)task->spawnArg1.value * 16 + 0x800), 0x100, rgb);
                    rgb[0] >>= 1;
                    rgb[1] >>= 1;
                    rgb[2] >>= 1;
                    Gp_DrawArc(coord, (s16)((u16)task->spawnArg1.value * 32 + 0xC00), 0xC0, rgb);
                    return;
                }
                scale        = work->scale;
                step         = (u16)work->step;
                work->scale  = scale + step;
                work->angle += (u16)work->step * 8;
                task->spawnArg1.value--;
                rgb[0] = work->scale;
                rgb[1] = work->scale >> 2;
                rgb[2] = work->scale >> 1;
                Gp_DrawRing(coord, work->angle, rgb);
                Gp_DrawRing(coord, (s16)((u16)work->angle * 2), rgb);
                Gp_DrawArc(coord, (s16)((u16)task->spawnArg1.value * 16 + 0x800), 0x100, rgb);
                rgb[0] >>= 1;
                rgb[1] >>= 1;
                rgb[2] >>= 1;
                Gp_DrawArc(coord, (s16)((u16)task->spawnArg1.value * 32 + 0xC00), 0xC0, rgb);
                if (task->spawnArg1.value == 0) {
                    work->scale  = 0xFF;
                    task->state  = 2;
                    work->period = 0x600;
                    work->step   = 0;
                }
                return;
            case 2:
                if (work->scale >= 0x11) {
                    rgb[0] = work->scale;
                    rgb[1] = work->scale >> 2;
                    rgb[2] = work->scale >> 1;
                    Gp_DrawRing(coord, work->angle, rgb);
                    Gp_DrawRing(coord, (s16)((u16)work->angle * 2), rgb);
                    if (gRoomEffectState->effectControl == ROOM_EFFECT_CONTROL_RUNNING) {
                        work->scale -= 0x10;
                        work->angle -= 0x60;
                    }
                    Gp_DrawFadeQuad(rgb, 1);
                } else {
                    task->state = 3;
                }
                func_shelter_r48_80181C14(coord, work->period, work->step, 0xC36);
                func_shelter_r48_80181C14(coord, work->period, (s16)-work->step, 0xC36);
                return;
            case 3:
                func_shelter_r48_80181C14(coord, work->period, work->step, 0xC36);
                func_shelter_r48_80181C14(coord, work->period, (s16)-work->step, 0xC36);
                if (gRoomEffectState->effectControl == ROOM_EFFECT_CONTROL_RUNNING) {
                    if (work->step < 0x200) {
                        work->period -= 0x18;
                        work->step   += 0x10;
                    } else {
                        task->state = 4;
                    }
                }
                return;
            case 4:
                if (work->period > 0) {
                    func_shelter_r48_80181C14(coord, work->period, work->step, 0xC36);
                    func_shelter_r48_80181C14(coord, work->period, (s16)-work->step, 0xC36);
                    if (gRoomEffectState->effectControl == ROOM_EFFECT_CONTROL_RUNNING) {
                        work->period -= 0x30;
                    }
                    return;
                }
                break;
            default:
                return;
        }
    }
    effectKillTask(work, task);
}

/// Offsets a point (0, 0x800, 0x1400) from `coord`, turned by `yaw` about Y
/// and then by the coordinate's world matrix, and projects both the
/// coordinate's world position and that tip through `GsWSMATRIX`. When both
/// project, it draws two passes of gouraud `POLY_G4` wedges, with radii of
/// `size * 64` and `size * 128` over each end's depth: every 0x400 step
/// across the half-turn facing along the screen-space line between the points
/// queues a fan at the tip, a fan at the base and a quad joining them. `color`
/// packs `0xRGB` nibbles, each shifted into its channel's high nibble, with
/// `gDisplayState.animFrame & 1` shifted into bit 4 of every channel.
static void func_shelter_r48_80181C14(GfxCoord* coord, s16 size, s32 yaw, s32 color)
{
    MATRIX           m;
    RoomBeamScratch* block;
    POLY_G4*         prim;
    s32              pass;
    u8               r;
    u8               g;
    u8               b;
    s32              limit;
    s32              angStart;
    s32              scaled;
    s32              ang;
    s32              next;
    s32              mid;
    s32              blend;
    s32              tr;
    s32              tg;

    block            = SCRATCH_STACK_RESERVE_BLOCK(RoomBeamScratch);
    block->point1.vy = 0x800;
    block->point1.vx = 0;
    block->point1.vz = 0x1400;
    gfxRotMatrixY(&m, (s16)yaw, 1);
    ang = color;
    gte_SetRotMatrix(&m);
    gte_ldv0(&block->point1);
    gte_rtv0();
    gte_stsv(&block->point1);
    gte_SetRotMatrix(&coord->workm);
    gte_ldv0(&block->point1);
    gte_rtv0();
    gte_stsv(&block->point1);
    block->point0.vx  = coord->workm.t[0];
    block->point0.vy  = coord->workm.t[1];
    block->point0.vz  = coord->workm.t[2];
    block->point1.vx += block->point0.vx;
    block->point1.vy += block->point0.vy;
    block->point1.vz += block->point0.vz;
    gte_SetTransMatrix(&GsWSMATRIX);
    gte_SetRotMatrix(&GsWSMATRIX);
    gte_ldv0(&block->point0);
    gte_rtps();
    gte_stsxy(&block->pair.sx0);
    gte_stflg(&block->pair.flag);
    if (block->pair.flag >= 0) {
        gte_stszotz(&block->pair.otz0);
        gte_ldv0(&block->point1);
        gte_rtps();
        gte_stsxy(&block->pair.sx1);
        gte_stflg(&block->pair.flag);
        gte_stszotz(&block->pair.otz1);
        if (block->pair.flag >= 0) {
            tr    = (((u16)ang >> 8) & 0xF) << 4;
            tg    = (((u16)ang >> 4) & 0xF) << 4;
            blend = ((u8)gDisplayState.animFrame & 1) << 4;
            r     = tr + blend;
            g     = tg + blend;
            // Dead: never read before the loop sets it, but it has to be
            // here for `b` to read `color` rather than the copy in `ang`.
            ang = 0;
            b   = ((color & 0xF) << 4) + blend;
            for (pass = 1; pass < 3; pass++) {
                scaled              = size * (pass << 6);
                block->pair.radius0 = scaled / block->pair.otz0;
                block->pair.radius1 = scaled / block->pair.otz1;
                ang                 = (s16)ratan2((s16)block->pair.sy1 - (s16)block->pair.sy0, (s16)block->pair.sx0 - (s16)block->pair.sx1);
                if (ang < ang + 0x800) {
                    angStart = ang;
                    limit    = ang + 0x800;
                    do {
                        prim           = gGpuPrimCursor;
                        gGpuPrimCursor = prim + 1;
                        setPolyG4(prim);
                        setRGB0(prim, 0, 0, 0);
                        setRGB1(prim, 0, 0, 0);
                        setRGB2(prim, r, g, b);
                        setRGB3(prim, 0, 0, 0);
                        prim->x0 = block->pair.sx1 + ((block->pair.radius1 * rsin(ang + 0x800)) >> 12);
                        prim->y0 = block->pair.sy1 + ((block->pair.radius1 * rcos(ang + 0x800)) >> 12);
                        prim->x1 = block->pair.sx1 + ((block->pair.radius1 * rsin(ang + 0xA00)) >> 12);
                        prim->y1 = block->pair.sy1 + ((block->pair.radius1 * rcos(ang + 0xA00)) >> 12);
                        prim->x2 = block->pair.sx1;
                        prim->y2 = block->pair.sy1;
                        prim->x3 = block->pair.sx1 + ((block->pair.radius1 * rsin(ang + 0xC00)) >> 12);
                        prim->y3 = block->pair.sy1 + ((block->pair.radius1 * rcos(ang + 0xC00)) >> 12);
                        addPrim(GPU_ORDERING_TABLE_ENTRY_AT_BYTE_OFFSET(((((u32)block->pair.otz1 << gDisplayState.otDepthShift) >> 2) & GPU_ORDERING_TABLE_DEPTH_BYTE_MASK)),
                                prim);
                        gpuSetPrimitiveBlendMode(prim, GPU_BLEND_ADD, block->pair.otz1);

                        prim           = gGpuPrimCursor;
                        gGpuPrimCursor = prim + 1;
                        setPolyG4(prim);
                        setRGB0(prim, 0, 0, 0);
                        setRGB1(prim, 0, 0, 0);
                        setRGB2(prim, r, g, b);
                        setRGB3(prim, 0, 0, 0);
                        prim->x0 = block->pair.sx0 + ((block->pair.radius0 * rsin(ang)) >> 12);
                        prim->y0 = block->pair.sy0 + ((block->pair.radius0 * rcos(ang)) >> 12);
                        prim->x1 = block->pair.sx0 + ((block->pair.radius0 * rsin(ang + 0x200)) >> 12);
                        prim->y1 = block->pair.sy0 + ((block->pair.radius0 * rcos(ang + 0x200)) >> 12);
                        next     = ang + 0x400;
                        prim->x2 = block->pair.sx0;
                        prim->y2 = block->pair.sy0;
                        prim->x3 = block->pair.sx0 + ((block->pair.radius0 * rsin(next)) >> 12);
                        prim->y3 = block->pair.sy0 + ((block->pair.radius0 * rcos(next)) >> 12);
                        addPrim(GPU_ORDERING_TABLE_ENTRY_AT_BYTE_OFFSET(((((u32)block->pair.otz0 << gDisplayState.otDepthShift) >> 2) & GPU_ORDERING_TABLE_DEPTH_BYTE_MASK)),
                                prim);
                        gpuSetPrimitiveBlendMode(prim, GPU_BLEND_ADD, block->pair.otz0);

                        prim           = gGpuPrimCursor;
                        mid            = angStart + (ang - angStart) * 2;
                        gGpuPrimCursor = prim + 1;
                        setPolyG4(prim);
                        setRGB0(prim, 0, 0, 0);
                        setRGB1(prim, 0, 0, 0);
                        setRGB2(prim, r, g, b);
                        setRGB3(prim, r, g, b);
                        prim->x0 = block->pair.sx0 + ((block->pair.radius0 * rsin(mid)) >> 12);
                        prim->y0 = block->pair.sy0 + ((block->pair.radius0 * rcos(mid)) >> 12);
                        prim->x1 = block->pair.sx1 + ((block->pair.radius1 * rsin(mid)) >> 12);
                        prim->y1 = block->pair.sy1 + ((block->pair.radius1 * rcos(mid)) >> 12);
                        prim->x2 = block->pair.sx0;
                        prim->y2 = block->pair.sy0;
                        prim->x3 = block->pair.sx1;
                        prim->y3 = block->pair.sy1;
                        addPrim(GPU_ORDERING_TABLE_ENTRY_AT_BYTE_OFFSET(((((u32)block->pair.otz1 << gDisplayState.otDepthShift) >> 2) & GPU_ORDERING_TABLE_DEPTH_BYTE_MASK)),
                                prim);
                        gpuSetPrimitiveBlendMode(prim, GPU_BLEND_ADD, block->pair.otz1);
                        ang = next;
                    } while (ang < limit);
                }
            }
        }
    }
    SCRATCH_STACK_RELEASE_BLOCK(RoomBeamScratch);
}

/// Projects `arg0` through `gGfxViewCoord.workm` and, when the GTE flag is
/// non-negative, queues a glow of gouraud `POLY_G4` wedges around the projected
/// point: an outer ring pairing a half-brightness wedge at full radius with a
/// full-brightness one at half radius, then four inner cross wedges in the
/// half-brightness colour. The depth is pulled 0xC0 towards the camera (clamped
/// at 16) before it sizes the radii and sorts the primitives. `arg1` is the
/// signed half-extent, and `arg2` packs `[flicker shift][r][g][b]` nibbles,
/// with `gDisplayState.animFrame & 1` shifted by the top nibble added to every
/// channel.
static void func_shelter_r48_8018258C(SVECTOR* arg0, s32 arg1, s32 arg2)
{
    GlowCentreRadiiScratch* block;
    POLY_G4*                prim;
    s32                     ang;
    s32                     t;
    s32                     t2;
    s32                     ua;
    s32                     ub;
    s32                     uc;
    s32                     frame;
    s32                     packed;
    s32                     blend;
    s32                     r;
    s32                     g;
    s32                     b;
    s32                     outer;
    s32                     inner;
    s32                     hr;
    s32                     hg;
    s32                     hb;

    block = SCRATCH_STACK_RESERVE_BLOCK(GlowCentreRadiiScratch);

    gte_SetTransMatrix(&gGfxViewCoord.workm);
    gte_SetRotMatrix(&gGfxViewCoord.workm);
    gte_ldv0(arg0);
    gte_rtps();
    gte_stsxy(&block->sx);
    gte_stflg(&block->flag);
    if (block->flag >= 0) {
        gte_stszotz(&block->otz);
        block->otz -= 0xC0;
        if (block->otz < 0x10) {
            block->otz = 0x10;
        }
        arg1             <<= 16;
        arg1             >>= 16;
        outer              = (arg1 * 64) / block->otz;
        frame              = gDisplayState.animFrame;
        block->outerRadius = outer;
        inner              = (arg1 * 8) / block->otz;
        ang                = 0;
        packed             = arg2 << 16;
        blend              = (frame & 1) << (packed >> 28);
        r                  = blend + ((packed >> 20) & 0xF0);
        g                  = blend + ((packed >> 16) & 0xF0);
        b                  = blend + ((arg2 & 0xF) << 4);
        block->innerRadius = inner;
        do {
            prim           = gGpuPrimCursor;
            gGpuPrimCursor = prim + 1;
            setPolyG4(prim);
            hr = (u8)r >> 1;
            setRGB0(prim, 0, 0, 0);
            setRGB1(prim, 0, 0, 0);
            hg = (u8)g >> 1;
            hb = (u8)b >> 1;
            setRGB2(prim, hr, hg, hb);
            setRGB3(prim, 0, 0, 0);
            prim->x0 = block->sx + ((block->outerRadius * rsin(ang)) >> 12);
            t        = ang + 0x100;
            prim->y0 = block->sy + ((block->outerRadius * rcos(ang)) >> 12);
            prim->x1 = block->sx + ((block->outerRadius * rsin(t)) >> 12);
            prim->y1 = block->sy + ((block->outerRadius * rcos(t)) >> 12);
            t2       = ang + 0x200;
            prim->x2 = block->sx;
            prim->y2 = block->sy;
            prim->x3 = block->sx + ((block->outerRadius * rsin(t2)) >> 12);
            prim->y3 = block->sy + ((block->outerRadius * rcos(t2)) >> 12);
            addPrim(GPU_ORDERING_TABLE_ENTRY_AT_BYTE_OFFSET(((((u32)block->otz << gDisplayState.otDepthShift) >> 2) & GPU_ORDERING_TABLE_DEPTH_BYTE_MASK)),
                    prim);
            gpuSetPrimitiveBlendMode(prim, GPU_BLEND_ADD, block->otz);

            prim           = gGpuPrimCursor;
            gGpuPrimCursor = prim + 1;
            setPolyG4(prim);
            setRGB0(prim, 0, 0, 0);
            setRGB1(prim, 0, 0, 0);
            setRGB2(prim, r, g, b);
            setRGB3(prim, 0, 0, 0);
            prim->x0 = block->sx + ((block->outerRadius * rsin(ang)) >> 13);
            prim->y0 = block->sy + ((block->outerRadius * rcos(ang)) >> 13);
            prim->x1 = block->sx + ((block->outerRadius * rsin(t)) >> 13);
            prim->y1 = block->sy + ((block->outerRadius * rcos(t)) >> 13);
            prim->x2 = block->sx;
            prim->y2 = block->sy;
            prim->x3 = block->sx + ((block->outerRadius * rsin(t2)) >> 13);
            prim->y3 = block->sy + ((block->outerRadius * rcos(t2)) >> 13);
            ang      = t2;
            addPrim(GPU_ORDERING_TABLE_ENTRY_AT_BYTE_OFFSET(((((u32)block->otz << gDisplayState.otDepthShift) >> 2) & GPU_ORDERING_TABLE_DEPTH_BYTE_MASK)),
                    prim);
            gpuSetPrimitiveBlendMode(prim, GPU_BLEND_ADD, block->otz);
        } while (ang < 0x1000);

        ang = 0x200;
        r   = (u8)hr;
        g   = (u8)hg;
        b   = (u8)hb;
        do {
            ua             = ang - 0x400;
            prim           = gGpuPrimCursor;
            gGpuPrimCursor = prim + 1;
            setPolyG4(prim);
            setRGB0(prim, 0, 0, 0);
            setRGB1(prim, 0, 0, 0);
            setRGB2(prim, r, g, b);
            setRGB3(prim, 0, 0, 0);
            prim->x0 = block->sx + ((block->innerRadius * rsin(ua)) >> 13);
            prim->y0 = block->sy + ((block->innerRadius * rcos(ua)) >> 13);
            prim->x1 = block->sx + ((block->outerRadius * rsin(ang)) >> 12);
            prim->y1 = block->sy + ((block->outerRadius * rcos(ang)) >> 12);
            ub       = ang + 0x400;
            prim->x2 = block->sx;
            prim->y2 = block->sy;
            prim->x3 = block->sx + ((block->innerRadius * rsin(ub)) >> 13);
            prim->y3 = block->sy + ((block->innerRadius * rcos(ub)) >> 13);
            addPrim(GPU_ORDERING_TABLE_ENTRY_AT_BYTE_OFFSET(((((u32)block->otz << gDisplayState.otDepthShift) >> 2) & GPU_ORDERING_TABLE_DEPTH_BYTE_MASK)),
                    prim);
            gpuSetPrimitiveBlendMode(prim, GPU_BLEND_ADD, block->otz);

            prim           = gGpuPrimCursor;
            gGpuPrimCursor = prim + 1;
            setPolyG4(prim);
            setRGB0(prim, 0, 0, 0);
            setRGB1(prim, 0, 0, 0);
            setRGB2(prim, r, g, b);
            setRGB3(prim, 0, 0, 0);
            prim->x0 = block->sx + ((block->innerRadius * rsin(ang)) >> 12);
            prim->y0 = block->sy + ((block->innerRadius * rcos(ang)) >> 12);
            prim->x1 = block->sx + ((block->outerRadius * rsin(ub)) >> 11);
            prim->y1 = block->sy + ((block->outerRadius * rcos(ub)) >> 11);
            uc       = ang + 0x800;
            prim->x2 = block->sx;
            prim->y2 = block->sy;
            prim->x3 = block->sx + ((block->innerRadius * rsin(uc)) >> 12);
            prim->y3 = block->sy + ((block->innerRadius * rcos(uc)) >> 12);
            ang      = uc;
            addPrim(GPU_ORDERING_TABLE_ENTRY_AT_BYTE_OFFSET(((((u32)block->otz << gDisplayState.otDepthShift) >> 2) & GPU_ORDERING_TABLE_DEPTH_BYTE_MASK)),
                    prim);
            gpuSetPrimitiveBlendMode(prim, GPU_BLEND_ADD, block->otz);
        } while (ang < 0x1000);
    }
    SCRATCH_STACK_RELEASE_BLOCK(GlowCentreRadiiScratch);
}
